function matchBlot(node: Node, delta: Delta, scroll: ScrollBlot) {
  const match = scroll.query(node);
  if (match == null) return delta;
  // @ts-expect-error
  if (match.prototype instanceof EmbedBlot) {
    const embed = {};
    // @ts-expect-error
    const value = match.value(node);
    if (value != null) {
      // @ts-expect-error
      embed[match.blotName] = value;
      // @ts-expect-error
      const formats = match.formats(node, scroll);
      // @ts-expect-error
      const supportedFormats = Object.keys(formats).reduce(
        (supported: Record<string, unknown>, key) => {
          if (scroll.query(key, Scope.INLINE | Scope.BLOCK) != null) {
            supported[key] = formats[key];
          }
          return supported;
        },
        {},
      );
      return new Delta().insert(embed, supportedFormats);
    }
  } else {
    // @ts-expect-error
    if (match.prototype instanceof BlockBlot && !deltaEndsWith(delta, '\n')) {
      delta.insert('\n');
    }
    // @ts-expect-error
    if (typeof match.formats === 'function') {
      const formatValue = match.formats(node, scroll);
      if (scroll.query(match.blotName, Scope.BLOT) != null) {
        // @ts-expect-error
        return applyFormat(delta, match.blotName, formatValue);
      }
    }
  }
  return delta;
}

